  b.innerHTML='<span class="rsym">'+r.sym+'</span>'
   +'<span class="rname">'+(TH?r.name[1]:r.name[0])+'</span>'
   +'<span class="rnote">'+r.note+'</span>';
  b.onclick=function(){toggleRune(r.id,b);};
  grid.appendChild(b);
 });
