function toggleRune(id,btn){
 var i=S.runes.indexOf(id);
 if(i>=0){S.runes.splice(i,1);btn.classList.remove('sel');}
 else{
  if(S.runes.length>=3){
   var gd=g('rune_grid');gd.classList.add('shake');
   setTimeout(function(){gd.classList.remove('shake');},350);return;
  }
  S.runes.push(id);btn.classList.add('sel');
 }
 g('rune_cnt').textContent=S.runes.length;
}

