  var td=document.createElement('div');td.className='ticks';td.id='tck_'+key;
  var vd=document.createElement('div');vd.className='stat-v';vd.id='sv_'+key;
  for(var i=1;i<=10;i++){
   (function(i){
    var t=document.createElement('div');
    t.className='tick'+(S.stats[key]>=i?' on':'')+(i>=9&&S.stats[key]>=i?' hi':'');
    t.onclick=function(){setStat(key,i);};
    td.appendChild(t);
   })(i);
  }
  vd.textContent=S.stats[key];
  row.appendChild(nd);row.appendChild(td);row.appendChild(vd);
  blk.appendChild(row);
 });
}

